  `phone` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `directory_contact_stage_id` bigint unsigned DEFAULT NULL,
  `last_contact` date DEFAULT NULL,
  `next_contact` date DEFAULT NULL,
  `comment` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `directory_contacts_directory_contact_stage_id_foreign` (`directory_contact_stage_id`),
  CONSTRAINT `directory_contacts_directory_contact_stage_id_foreign` FOREIGN KEY (`directory_contact_stage_id`) REFERENCES `directory_contact_stages` (`id`) ON DELETE SET NULL
